morseCodeDict = { '.-', '-...', '-.-.', '-..', '.', '..-', '--.', '....', '..', '.--', '--.-', '.-.', '.-..', '--', '-.', '---', '.--.', '--.-', '-.', '---', '----.' };

% Function to convert a single character to Morse Code
function [morseCode] = morseCodeFromChar(char)
    % Convert char to uppercase
    char = upper(char);

    % Find index of char in dictionary
    idx = find(strcmpi(morseCodeDict, char));

    % Return Morse Code if found, otherwise return dash sequence
    if ~isempty(idx)
        morseCode = morseCodeDict(idx);
    else
        morseCode = repmat('-', length(char), 1);
    end
end

% Function to convert a whole phrase to Morse Code
function [morseCode] = morseCodeFromPhrase(phrase)
    % Convert phrase to uppercase
    phrase = upper(phrase);

    % Initialize empty string to store Morse Code
    morseCode = '';

    % Loop through each character in phrase
    for I = 1:length(phrase)
        % Call function to get Morse Code for current character
        morseCodeSeg = morseCodeFromChar(phrase(i));

        % Add space between characters
        if i ~= length(phrase)
            morseCode = [morseCode morseCodeSeg ' '];
        else
            morseCode = [morseCode morseCodeSeg];
        end
    end

    % Return Morse Code with leading/trailing spaces removed
    morseCode = strjoin(morseCode(:));
end
```

